algorithm:
UnifiedAdaptiveSequenceOptimizer(ProblemSpec, TimeLimit, Params)
  // ProblemSpec must provide: N (items), Evaluate(seq) -> cost, Feasible(seq) -> bool,
  // Repair(seq) -> seq (enforces problem constraints, e.g. CVRP split/repair), 
  // Neighborhood(seq) -> generator, ConstructInitial() -> seq
  subseqMemory ← empty structure for high-quality subsequences
  elite ← empty bounded list; population ← [ConstructInitial() or RandomPerm() for i in 1..Params.initPopSize]
  evaluate population and populate elite and subseqMemory with top solutions
  while not TerminationCondition(TimeLimit, Params):
    parents ← SelectParents(population, Params)
    child ← CombinePreservingSubsequences(parents, subseqMemory, Params)   // crossover that biases known good subsequences
    child ← Repair(child, ProblemSpec)                                     // enforce capacity, machine-order, etc.
    child ← AdaptiveLocalSearch(child, Neighborhood, Evaluate, Params)     // iterative intensification (e.g., 2-opt, insertion, swap)
    if not Feasible(child): child ← PenaltyGuidedRepair(child, ProblemSpec) // constraint-handling fallback
    population ← Replace(population, child, Params)                        // elitist or steady-state replacement
    Update(elite, subseqMemory, child, Evaluate, Params)                   // learn subsequences, update archive
    if StagnationDetected(population, elite, Params): Diversify(population, elite, Params)
  return BestPermutation(elite)
